      region: "US-CA",
    });
    cart.add(product("a", 1000), 10); // subtotal 10000, discount 2000, discountedSub 8000
    const t = cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(8000, "US-CA");
    expect(t.taxCents).toBe(240);
  });

  it("passes lines and discounted subtotal to shipping", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(1000),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    cart.add(product("a", 2000, 500), 3); // subtotal 6000, discount 1000, discounted 5000
