    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    cart.add(product("a", 2000, 500), 3); // subtotal 6000, discount 1000, discounted 5000
    const t = cart.totals();
    expect(shipping.computeShippingCents).toHaveBeenCalled();
    const [lines, subtotal] = (shipping.computeShippingCents as ReturnType<typeof vi.fn>).mock.calls[0];
    expect(subtotal).toBe(5000);
    expect(lines).toHaveLength(1);
    expect(t.shippingCents).toBe(599);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
