      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),
          new FixedAmountDiscountPolicy(500),
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10_000)).toBe(1_500);
    });

    it("ordering matters: larger discount first yields different result", () => {
      // 50% then fixed-3000 on 10000:
      //   50% of 10000 = 5000, remaining 5000
      //   fixed 3000 on 5000 = 3000
      //   total = 8000
      const a = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50),
          new FixedAmountDiscountPolicy(3000),
        ],
        "chain",
      );
      // fixed-3000 then 50%:
      //   fixed 3000 on 10000 = 3000, remaining 7000
      //   50% of 7000 = 3500
      //   total = 6500
      const b = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(3000),
          new PercentageDiscountPolicy(50),
        ],
        "chain",
      );
      expect(a.computeDiscountCents(10_000)).toBe(8_000);
      expect(b.computeDiscountCents(10_000)).toBe(6_500);
    });

    it("stops when remaining reaches 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(100), // takes everything
          new FixedAmountDiscountPolicy(500), // nothing left
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10_000)).toBe(10_000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});
"}

