toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it("returns 0 for any taxable amount", () => {
    expect(calc.computeTaxCents(10_000, "US")).toBe(0);
  });

  it("returns 0 for zero taxable", () => {
    expect(calc.computeTaxCents(0, "FR")).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  it("rejects defaultRate < 0", () => {
    expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
  });

  it("rejects defaultRate > 1", () => {
    expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
  });

  it("rejects NaN defaultRate", () => {
    expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
  });

  it("rejects invalid rate for a region", () => {
    expect(
      () => new RegionalTaxCalculator({ "US": 1.5 }),
    ).toThrow(RangeError);
  });

  it("rejects negative rate for a region", () => {
    expect(
      () => new RegionalTaxCalculator({ "US": -0.1 }),
    ).toThrow(RangeError);
  });

  it("uses region rate when available", () => {
    const calc = new RegionalTaxCalculator({ "US-CA": 0.0875 });
    // 8.75% of 10000 = 875
    expect(calc.computeTaxCents(10_000, "US-CA")).toBe(875);
  });

  it("falls back to default rate for unknown region", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.08 }, 0.05);
    // 5% of 10000 = 500
    expect(calc.computeTaxCents(10_000, "FR")).toBe(500);
  });

  it("defaults default rate to 0 when omitted", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.08 });
    expect(calc.computeTaxCents(10_000, "FR")).toBe(0);
  });

  it("returns 0 for zero taxable", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.08 });
    expect(calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.08 });
    expect(calc.computeTaxCents(-500, "US")).toBe(0);
  });

  it("rounds down fractional cents", () => {
    // 8% of 999 = 79.92 → 79
    const calc = new RegionalTaxCalculator({ "US": 0.08 });
    expect(calc.computeTaxCents(999, "US")).toBe(79);
  });

  it("accepts boundary rates 0 and 1", () => {
    const calc = new RegionalTaxCalculator({ "A": 0, "B": 1 });
    expect(calc.computeTaxCents(1000, "A")).toBe(0);
    expect(calc.computeTaxCents(1000, "B")).toBe(1000);
  });
});

describe("AsyncTaxCalculator", () => {
  it("returns 0 when taxable is 0", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("returns 0 when taxable is negative", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-100, "US")).toBe(0);
  });

  it("computes tax using provided rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(10_000, "US")).toBe(1_000);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("rounds down fractional cents", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.075),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 7.5% of 999 = 74.925 → 74
    expect(await calc.computeTaxCents(999, "US")).toBe(74);
  });

  it("throws on rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10_000, "US")).rejects.toThrow(
      RangeError,
    );
  });

  it("throws on negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10_000, "US")).rejects.toThrow(
      RangeError,
    );
  });

  it("throws on NaN rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10_000, "US")).rejects.toThrow(
      RangeError,
    );
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network error")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10_000, "US")).rejects.toThrow(
      "network error",
    );
  });
});

describe("totalLineWeightGrams", () => {
  it("returns 0 for empty array", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });

  it("sums weight * quantity", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 200 }, quantity: 3 },
      { product: { id: "b", name: "B", unitPriceCents: 100, weightGrams: 500 }, quantity: 2 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(200 * 3 + 500 * 2);
  });

  it("treats undefined weight as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });
});

