+  it("returns totals and lines for empty collaborators", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 2);
+    const result = await cart.checkout();
+    expect(result.totals.subtotalCents).toBe(2000);
+    expect(result.lines).toHaveLength(1);
+  });
+
+  it("refreshes prices via priceFetcher", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 1);
+
+    const priceFetcher: PriceFetcher = {
+      fetchPriceCents: vi.fn().mockResolvedValue(2000),
+    };
+    const result = await cart.checkout({ priceFetcher });
+    expect(result.totals.subtotalCents).toBe(2000);
+    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
+  });
+
+  it("throws InventoryError when inventory unavailable", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 5);
+
+    const inventoryChecker: InventoryChecker = {
+      check: vi.fn().mockResolvedValue({
+        available: false,
+        availableQuantity: 2,
+        reason: "low stock",
+      }),
+    };
+    try {
+      await cart.checkout({ inventoryChecker });
+      expect.unreachable("should have thrown");
+    } catch (err) {
+      expect(err).toBeInstanceOf(InventoryError);
+      const ie = err as InventoryError;
+      expect(ie.productId).toBe("a");
+      expect(ie.requested).toBe(5);
+      expect(ie.available).toBe(2);
+      expect(ie.message).toBe("low stock");
+    }
+  });
+
+  it("throws InventoryError on partial-stock denial (available=true but qty < requested)", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 10);
+
+    const inventoryChecker: InventoryChecker = {
+      check: vi.fn().mockResolvedValue({
+        available: true,
+        availableQuantity: 3,
+      }),
+    };
+    try {
+      await cart.checkout({ inventoryChecker });
+      expect.unreachable("should have thrown");
+    } catch (err) {
+      expect(err).toBeInstanceOf(InventoryError);
+      const ie = err as InventoryError;
+      expect(ie.productId).toBe("a");
+      expect(ie.requested).toBe(10);
+      expect(ie.available).toBe(3);
+    }
+  });
+
+  it("succeeds when inventory is available", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 2);
+
+    const inventoryChecker: InventoryChecker = {
+      check: vi.fn().mockResolvedValue({ available: true }),
+    };
+    const result = await cart.checkout({ inventoryChecker });
+    expect(result.totals.subtotalCents).toBe(2000);
+  });
+
+  it("uses asyncTaxProvider when supplied", async () => {
+    const discount: DiscountPolicy = {
+      computeDiscountCents: vi.fn().mockReturnValue(0),
+    };
+    const shipping: ShippingCalculator = {
+      computeShippingCents: vi.fn().mockReturnValue(500),
+    };
+    const cart = new Cart({
+      discountPolicy: discount,
+      shippingCalculator: shipping,
+      region: "US-CA",
+    });
+    cart.add(product("a", 1000), 10); // subtotal 10000
+
+    const asyncTaxProvider: AsyncTaxRateProvider = {
+      getRate: vi.fn().mockResolvedValue(0.1),
+    };
+    const result = await cart.checkout({ asyncTaxProvider });
+    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
+    expect(result.totals.taxCents).toBe(1000); // 10% of 10000
+    expect(result.totals.shippingCents).toBe(500);
+    expect(result.totals.totalCents).toBe(10000 + 1000 + 500);
+  });
+
+  it("composes discount + async tax + shipping correctly", async () => {
+    const discount: DiscountPolicy = {
+      computeDiscountCents: vi.fn().mockReturnValue(2000),
+    };
+    const shipping: ShippingCalculator = {
+      computeShippingCents: vi.fn().mockReturnValue(300),
+    };
+    const cart = new Cart({
+      discountPolicy: discount,
+      shippingCalculator: shipping,
+      region: "FR",
+    });
+    cart.add(product("a", 1000), 10); // subtotal 10000, discount 2000, discounted 8000
+
+    const asyncTaxProvider: AsyncTaxRateProvider = {
+      getRate: vi.fn().mockResolvedValue(0.2),
+    };
+    const result = await cart.checkout({ asyncTaxProvider });
+    // tax = floor(8000 * 0.2) = 1600
+    expect(result.totals.subtotalCents).toBe(10000);
+    expect(result.totals.discountCents).toBe(2000);
+    expect(result.totals.taxCents).toBe(1600);
+    expect(result.totals.shippingCents).toBe(300);
+    expect(result.totals.totalCents).toBe(8000 + 1600 + 300);
+  });
+
+  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
+    const cart = new Cart({ region: "US" });
+    cart.add(product("a", 100), 2);
+
+    const priceFetcher: PriceFetcher = {
+      fetchPriceCents: vi.fn().mockResolvedValue(500),
+    };
+    const inventoryChecker: InventoryChecker = {
+      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
+    };
+    const asyncTaxProvider: AsyncTaxRateProvider = {
+      getRate: vi.fn().mockResolvedValue(0.05),
+    };
+
+    const result = await cart.checkout({
+      priceFetcher,
+      inventoryChecker,
+      asyncTaxProvider,
+    });
+    // price refreshed to 500 * 2 = 1000
+    expect(result.totals.subtotalCents).toBe(1000);
+    expect(result.totals.taxCents).toBe(50); // 5% of 1000
+  });
+
+  it("propagates priceFetcher rejection", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 1);
+    const priceFetcher: PriceFetcher = {
+      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price error")),
+    };
+    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price error");
+  });
+
+  it("propagates asyncTaxProvider rejection", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 1);
+    const asyncTaxProvider: AsyncTaxRateProvider = {
+      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
+    };
+    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
+      "tax service down",
+    );
+  });
+
+  it("generates default error message when no reason given", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 5);
+    const inventoryChecker: InventoryChecker = {
+      check: vi.fn().mockResolvedValue({ available: false }),
+    };
+    try {
+      await cart.checkout({ inventoryChecker });
+      expect.unreachable("should have thrown");
+    } catch (err) {
+      expect(err).toBeInstanceOf(InventoryError);
+      expect((err as InventoryError).message).toContain("insufficient stock");
+    }
+  });
+});
